def countFixedMinMax(nums, minK, maxK):
    def inside(lo, hi):
        if lo > hi:
            return 0
        run = 0
        total = 0
        for v in nums:
            run = run + 1 if lo <= v <= hi else 0
            total += run
        return total
    return (inside(minK, maxK) - inside(minK + 1, maxK)
            - inside(minK, maxK - 1) + inside(minK + 1, maxK - 1))
